 const retry=fixture(f.disk(),f.storage);assert.equal(retry.plan.pendingTransition.kind,'delete');await retry.plan.ensureLifecycle();assert.equal(retry.plan.active(),null);assert.equal(retry.plan.listHistorical().length,0);
 f=fixture();const finished=await f.plan.createPlan();await f.plan.finishPlan(finished);assert.equal(f.plan.finishedPreviewPlanId,finished);assert.equal(fixture(f.disk(),f.storage).plan.finishedPreviewPlanId,undefined);f.plan.dismissHomePlan(finished);assert.equal(f.plan.finishedPreviewPlanId,null);assert(f.plan.readPlan(finished));

 f=fixture();const unprotected=await f.plan.createPlan();f.plan.setNote('Durable original');await f.plan.flush();f.plan.recovery.storage.setItem=()=>{throw Error('checkpoint unavailable');};f.fail(true);await assert.rejects(f.plan.deletePlan(unprotected,{confirmed:true}));assert.equal(f.plan.active().content.note,'Durable original');assert.equal(fixture(f.disk()).plan.active().content.note,'Durable original');
