 assert.equal(f.plan.readPlan(exact).archiveReason,'never-activated');
 assert.equal(f.plan.readPlan(exact).startedAt,null);
 assert.equal(f.plan.readPlan(exact).snapshot.note,'Held note');
 assert.equal(f.plan.readPlan(exact).snapshot.entries[0].taskState,'completed');
